def _make_patients(gene: str, n: int = 40) -> list[dict]:
    prof = PROFILES[gene]
    rng = random.Random(SEEDS[gene])
    patients = []
    for i in range(n):
        age_min, age_max = prof["age_onset_range"]
        age_onset = round(rng.uniform(age_min, age_max), 1)
        age_current = round(rng.uniform(max(age_onset + 1, age_onset), age_onset + 30), 1)

        sex = "M" if (prof["x_linked"] and rng.random() < 0.90) else rng.choice(["M", "F"])

        infections         = rng.random() < prof["infect_prob"]
        sle_features       = rng.random() < prof["sle_prob"]
        neisseria_episode  = rng.random() < prof["neisseria_prob"]
        aHUS_episode       = rng.random() < prof["aHUS_prob"]
        adult_onset        = rng.random() < prof["adult_onset_prob"]
        eculizumab_on      = rng.random() < (0.68 if prof["eculizumab"] else 0.0)
        meningococcal_vax  = rng.random() < (0.85 if prof["meningococcal_vaccine"] else 0.20)
        abx_prophylaxis    = rng.random() < (0.80 if infections else 0.30)
        c3_low             = rng.random() < (0.95 if gene in ["C3", "CFI"] else
                                              0.72 if gene == "CFH" else 0.10)
        ch50_absent        = rng.random() < (0.95 if gene in ["C3", "C1QB", "C2", "C5", "C6", "CFI"] else
                                              0.30 if gene == "CFH" else 0.05)
        ah50_absent        = rng.random() < (0.95 if gene in ["C3", "C5", "C6", "CFH", "CFI", "CFP"] else
                                              0.10 if gene in ["C1QB", "C2"] else 0.05)
        ffp_received       = rng.random() < (0.45 if gene in ["C3", "CFH", "CFI"] else 0.15)
        infections_per_yr  = round(rng.uniform(3, 8) if infections and age_onset < 15
                                    else rng.uniform(0.5, 3.0), 1)

        patients.append({
            "gene":              gene,
            "age_onset":         age_onset,
            "age_current":       age_current,
            "sex":               sex,
            "infections":        infections,
            "sle_features":      sle_features,
            "neisseria_episode": neisseria_episode,
            "aHUS_episode":      aHUS_episode,
            "adult_onset":       adult_onset,
            "eculizumab_on":     eculizumab_on,
            "meningococcal_vax": meningococcal_vax,
            "abx_prophylaxis":   abx_prophylaxis,
            "c3_low":            c3_low,
            "ch50_absent":       ch50_absent,
            "ah50_absent":       ah50_absent,
            "ffp_received":      ffp_received,
            "infections_per_yr": infections_per_yr,
        })
    return patients


def _cohort_stats(patients: list[dict]) -> dict:
    n = len(patients)
    return {
        "n":                    n,
        "infections_n":         sum(1 for p in patients if p["infections"]),
        "sle_n":                sum(1 for p in patients if p["sle_features"]),
        "neisseria_n":          sum(1 for p in patients if p["neisseria_episode"]),
        "aHUS_n":               sum(1 for p in patients if p["aHUS_episode"]),
        "eculizumab_n":         sum(1 for p in patients if p["eculizumab_on"]),
        "meningococcal_vax_n":  sum(1 for p in patients if p["meningococcal_vax"]),
        "abx_n":                sum(1 for p in patients if p["abx_prophylaxis"]),
        "c3_low_n":             sum(1 for p in patients if p["c3_low"]),
        "ch50_absent_n":        sum(1 for p in patients if p["ch50_absent"]),
        "ah50_absent_n":        sum(1 for p in patients if p["ah50_absent"]),
        "ffp_n":                sum(1 for p in patients if p["ffp_received"]),
        "adult_onset_n":        sum(1 for p in patients if p["adult_onset"]),
        "mean_age_onset":       round(statistics.mean(p["age_onset"] for p in patients), 1),
        "mean_infections_yr":   round(statistics.mean(p["infections_per_yr"] for p in patients), 1),
    }


